"""Build worker/test/fixtures/golden_seed.sql: the slice of the real build/fund.db the golden tests read.

Run from etl/:  uv run python ../worker/test/fixtures/make_golden_seed.py [--db ../build/fund.db]

The golden questions (golden/golden_questions.md) and the 20-fund hand-check replay
(golden/handcheck_replay.csv) only touch a few advisers, their funds and Form D filings, plus one
month of new launches. This copies every row those tool calls can read, so the committed file keeps
`npm test` offline (CI has no fund.db) while giving the same answers as the full database. To check
that claim, run the golden suite against a local D1 holding all of fund.db:

    cd etl && uv run python -m etl.export_sql            # build/sql/ from build/fund.db
    cd ../worker && GOLDEN_SQL_DIR=../build/sql npx vitest run test/golden.test.ts
"""

from __future__ import annotations

import argparse
import csv
import sqlite3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
OUT = Path(__file__).with_name("golden_seed.sql")

# Advisers named in golden/golden_questions.md (the hand-check advisers are added from handcheck.csv).
GOLDEN_CRDS = {
    "160391", "308145",  # Q1 Uncork Capital, two near-duplicate advisers
    "156612",            # Q2, Q7 Weathergage Capital
    "322432",            # Q3 Ethereal Ventures (feeders)
    "299541",            # Q4 Eagle Capital International (indefinite offering)
    "165808",            # Q6 Standard Capital Advisors (fund with no Form D file number)
    "111035",            # Q8 Coller Investment Management (fund with four Form D file numbers)
    "299961",            # Q9 Third Lake Partners (VC/PE filter)
    "161768",            # Q10 Bridgescale (file number with no Form D on EDGAR)
}
# Name prefixes searched by resolve_manager in the questions: every adviser that starts with one is copied.
NAME_PREFIXES = ("uncork capital", "ethereal ventures", "weathergage")
# Q5: every first-time fund notice in this window, all states, so the state filter pages exactly as in production.
LAUNCH_WINDOW = ("2026-08-01", "2026-08-31")
META_KEYS = ("as_of_form_d", "as_of_form_adv", "form_d_since")


def lit(v) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, (int, float)):
        return str(v)
    return "'" + str(v).replace("'", "''") + "'"


def main() -> None:
    p = argparse.ArgumentParser()
    p.add_argument("--db", type=Path, default=ROOT / "build" / "fund.db")
    args = p.parse_args()
    db = sqlite3.connect(f"file:{args.db}?mode=ro", uri=True)
    with (ROOT / "golden" / "handcheck.csv").open(newline="") as fh:
        crds = GOLDEN_CRDS | {r["adviser_crd"] for r in csv.DictReader(fh)}
    for prefix in NAME_PREFIXES:
        crds |= {r[0] for r in db.execute("SELECT crd FROM advisers WHERE name_norm >= ? AND name_norm < ?",
                                          (prefix, prefix + "￿"))}

    db.execute("CREATE TEMP TABLE c (crd TEXT PRIMARY KEY)")
    db.executemany("INSERT INTO c VALUES (?)", [(c,) for c in sorted(crds)])
    db.execute("CREATE TEMP TABLE p AS SELECT pfid FROM funds WHERE adviser_crd IN (SELECT crd FROM c)")
    db.execute("""CREATE TEMP TABLE n AS
                  SELECT form_d_file_no file_no FROM funds WHERE pfid IN (SELECT pfid FROM p) AND form_d_file_no IS NOT NULL
                  UNION SELECT file_no FROM fund_file_nos WHERE pfid IN (SELECT pfid FROM p)""")
    # rowid order is kept: list_funds and new_launches page by rowid, so ties order the same as in D1.
    queries = {
        "advisers": "SELECT * FROM advisers WHERE crd IN (SELECT crd FROM c) ORDER BY rowid",
        "funds": "SELECT * FROM funds WHERE pfid IN (SELECT pfid FROM p) ORDER BY rowid",
        "fund_file_nos": "SELECT * FROM fund_file_nos WHERE pfid IN (SELECT pfid FROM p) ORDER BY rowid",
        "formd_offerings": f"""SELECT * FROM formd_offerings WHERE file_no IN (SELECT file_no FROM n)
                               OR (is_fund = 1 AND is_amendment = 0 AND filing_date BETWEEN {lit(LAUNCH_WINDOW[0])} AND {lit(LAUNCH_WINDOW[1])})
                               ORDER BY rowid""",
        "meta": f"SELECT * FROM meta WHERE key IN ({', '.join(lit(k) for k in META_KEYS)}) ORDER BY key",
    }
    lines = [f"-- Generated by make_golden_seed.py from build/fund.db (real SEC rows; see that script). Do not edit."]
    counts = {}
    for table, sql in queries.items():
        cur = db.execute(sql)
        cols = ", ".join(d[0] for d in cur.description)
        n = 0
        for row in cur:
            lines.append(f"INSERT INTO {table} ({cols}) VALUES ({', '.join(lit(v) for v in row)});")
            n += 1
        counts[table] = n
    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {OUT}: {counts}")


if __name__ == "__main__":
    main()
